CREATE TABLE CPF_CACHE_INVALIDATION_EVENT (
    EVENT_ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    EVENT_KEY VARCHAR2(180 CHAR) NOT NULL,
    TENANT_ID VARCHAR2(80 CHAR) NOT NULL,
    NAMESPACE_NAME VARCHAR2(80 CHAR) NOT NULL,
    CACHE_KEY_VALUE VARCHAR2(512 CHAR) NULL,
    EVENT_VERSION NUMBER(19) DEFAULT 0 NOT NULL,
    REASON_TEXT VARCHAR2(500 CHAR) NOT NULL,
    REQUESTED_BY VARCHAR2(180 CHAR) NOT NULL,
    CREATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT UK_CPF_CACHE_INV_EVENT_KEY UNIQUE (EVENT_KEY),
    CONSTRAINT CK_CPF_CACHE_INV_VERSION CHECK (EVENT_VERSION >= 0)
);
CREATE INDEX IX_CPF_CACHE_INV_CREATED ON CPF_CACHE_INVALIDATION_EVENT (CREATED_AT);
CREATE INDEX IX_CPF_CACHE_INV_TARGET ON CPF_CACHE_INVALIDATION_EVENT (TENANT_ID, NAMESPACE_NAME, EVENT_ID);
CREATE TABLE CPF_CACHE_INVALIDATION_CHECKPOINT (
    CONSUMER_ID VARCHAR2(180 CHAR) PRIMARY KEY,
    LAST_EVENT_ID NUMBER(19) DEFAULT 0 NOT NULL,
    UPDATED_AT TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT CK_CPF_CACHE_INV_CHECKPOINT CHECK (LAST_EVENT_ID >= 0)
);
